#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<pair<long long, long long>> items(n);  // (original size, unit cost)
    for (auto &it : items) cin >> it.first;
    for (auto &it : items) cin >> it.second;
    sort(items.begin(), items.end());
    // Products whose original size is <= pos: highest unit cost first, then smaller size.
    priority_queue<pair<long long, long long>> heap;
    long long pos = 0, answer = 0;
    int i = 0;
    while (i < n || !heap.empty()) {
        if (heap.empty()) pos = max(pos, items[i].first);  // jump over empty coordinates
        while (i < n && items[i].first <= pos) {
            heap.push({items[i].second, -items[i].first});
            i++;
        }
        auto [cost, negStart] = heap.top();
        heap.pop();
        answer += (pos + negStart) * cost;
        pos++;
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] size = new long[n];
        for (int i = 0; i < n; i++) size[i] = nextLong();
        // Sorted (size, cost) pairs; cost < 2^14, so both fit in one long.
        long[] items = new long[n];
        for (int i = 0; i < n; i++) items[i] = size[i] << 14 | nextLong();
        Arrays.sort(items);
        // Heap key of an available product: higher cost first, then smaller original size.
        final long mask = (1L << 31) - 1;
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        long pos = 0, answer = 0;
        int i = 0;
        while (i < n || !heap.isEmpty()) {
            if (heap.isEmpty()) pos = Math.max(pos, items[i] >> 14);  // jump over empty coordinates
            while (i < n && (items[i] >> 14) <= pos) {
                long s = items[i] >> 14, c = items[i] & ((1 << 14) - 1);
                heap.add(c << 31 | (mask - s));
                i++;
            }
            long key = heap.poll();
            long cost = key >>> 31, start = mask - (key & mask);
            answer += (pos - start) * cost;
            pos++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"container/heap"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type maxHeap []int64

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	size := make([]int64, n)
	for i := range size {
		size[i] = nextInt()
	}
	// Sorted (size, cost) pairs; cost < 2^14, so both fit in one int64.
	items := make([]int64, n)
	for i := range items {
		items[i] = size[i]<<14 | nextInt()
	}
	slices.Sort(items)
	// Heap key of an available product: higher cost first, then smaller original size.
	const mask = int64(1)<<31 - 1
	h := &maxHeap{}
	var pos, answer int64
	i := 0
	for i < n || h.Len() > 0 {
		if h.Len() == 0 {
			pos = max(pos, items[i]>>14) // jump over empty coordinates
		}
		for i < n && items[i]>>14 <= pos {
			s, c := items[i]>>14, items[i]&(1<<14-1)
			heap.Push(h, c<<31|(mask-s))
			i++
		}
		key := heap.Pop(h).(int64)
		cost, start := key>>31, mask-key&mask
		answer += (pos - start) * cost
		pos++
	}
	fmt.Println(answer)
}
